:root {
  /* Colors */
  --color-sunbeam-action: #ffdd00;
  --color-paper-canvas: #ffffff;
  --color-cream-tile: #faf8f0;
  --color-frosted-glass: #ffffffb3;
  --color-mist-well: #2222220d;
  --color-ink: #222222;
  --color-jet-heading: #000000;
  --color-graphite-caption: #717171;
  --color-pebble-skeleton: #e1e1e1;
  --color-ash-hairline: #2222221a;
  --color-ember-signal: #d8573f;
  --color-ember-wash: #d8573f0d;
  --color-sand-mock: #f7d046;

  /* Typography — Font Families */
  --font-circular: "Circular", "Figtree", "DM Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-sans-serif: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 22px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.333;
  --tracking-subheading: 0px;
  --text-heading-sm: 40px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: 0px;
  --text-heading: 64px;
  --leading-heading: 1.25;
  --tracking-heading: -2px;
  --text-display: 96px;
  --leading-display: 0.99;
  --tracking-display: -2.4px;
  --tracking-eyebrow: 2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-9: 9px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 936px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 16px;
  --layout-nav-height: 72px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-3xl: 32px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 32px;
  --radius-small-cards: 16px;
  --radius-inner-tiles: 24px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-inputs: 9999px;
  --radius-avatars: 9999px;
  --radius-images: 8px;
  --radius-tags: 4px;
  --radius-small-elements: 2px;
  --radius-sections: 32px 32px 0px 0px;

  /* Shadows */
  --shadow-sm: 0px 0px 2px 0px rgba(0,0,0,0.15), 0px 8px 40px 0px rgba(0,0,0,0.04), 0px 2px 5px 0px rgba(0,0,0,0.05);
  --shadow-md: 0px 0px 3px 0px rgba(0,0,0,0.15), 0px 11px 56px 0px rgba(0,0,0,0.04), 0px 3px 7px 0px rgba(0,0,0,0.05);
  --shadow-lg: 0px 0px 4px 0px rgba(0,0,0,0.15), 0px 16px 80px 0px rgba(0,0,0,0.04), 0px 4px 10px 0px rgba(0,0,0,0.05);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-well: #2222220d;
  --surface-cream-tile: #faf8f0;
  --surface-frosted-glass: #ffffffb3;
}

